import * as React from "react";

type IconProps = React.SVGAttributes<SVGSVGElement> & { size?: number | string };

const makeIcon = (d: string) => {
  const Icon = ({ size = 24, className, ...props }: IconProps) => (
    <svg
      viewBox="0 0 24 24"
      xmlns="http://www.w3.org/2000/svg"
      width={size}
      height={size}
      fill="currentColor"
      className={className}
      {...props}
    >
      <path d={d} />
    </svg>
  );
  return Icon;
};

